theorem algebra_5910 (x : ℝ) (y : ℕ) (hy : y > 0) (h1 : x^2 + 3 * y = 55) (h2 : 3 * x^2 * y + 6 * y^2 = 612) :
    y = 4 := by
  have h_main : y = 4 := by
    have h3 : y ≤ 55 := by
      by_contra h
      have h4 : y ≥ 56 := by linarith
      have h5 : x ^ 2 + 3 * y = 55 := h1
      have h6 : x ^ 2 = 55 - 3 * y := by linarith
      have h7 : (x ^ 2 : ℝ) ≥ 0 := by nlinarith
      have h8 : (55 : ℝ) - 3 * y ≤ 0 := by
        have h9 : (y : ℝ) ≥ 56 := by exact_mod_cast h4
        nlinarith
      have h9 : (x ^ 2 : ℝ) ≥ 0 := by nlinarith
      nlinarith
    -- We now know that y ≤ 55. We can use this to bound the possible values of y.
    interval_cases y <;> norm_num at h1 h2 ⊢ <;>
      (try omega) <;>
      (try {
        nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
      }) <;>
      (try {
        have h4 : x ^ 2 ≥ 0 := by nlinarith
        nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
      }) <;>
      (try {
        omega
      }) <;>
      (try {
        nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
      })
    <;>
    (try {
      nlinarith
    }) <;>
    (try {
      ring_nf at h1 h2 ⊢
      nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
    })
    <;>
    (try {
      nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
    })
    <;>
    (try {
      nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
    })
    <;>
    (try {
      nlinarith [sq_nonneg (x ^ 2 - 43), sq_nonneg (x ^ 2 - 43 / 2)]
    })
  exact h_main

