  have h_main : {n : ℕ | 10 ≤ n ∧ n < 100 ∧ ∃ k, k^2 = (Nat.digits 10 n).sum} = {10, 13, 22, 31, 40, 18, 27, 36, 45, 54, 63, 72, 81, 90, 79, 88, 97} := by
    apply Set.Subset.antisymm
    · -- Prove the forward inclusion: if n is in the LHS, then n is in the RHS
      intro n hn
      have h₁ : 10 ≤ n := hn.1
      have h₂ : n < 100 := hn.2.1
      have h₃ : ∃ k, k ^ 2 = (Nat.digits 10 n).sum := hn.2.2
      have h₄ : n = 10 ∨ n = 13 ∨ n = 22 ∨ n = 31 ∨ n = 40 ∨ n = 18 ∨ n = 27 ∨ n = 36 ∨ n = 45 ∨ n = 54 ∨ n = 63 ∨ n = 72 ∨ n = 81 ∨ n = 90 ∨ n = 79 ∨ n = 88 ∨ n = 97 := by
        -- We need to show that n is one of the specified numbers
        have h₅ : n < 100 := h₂
        have h₆ : 10 ≤ n := h₁
        have h₇ : ∃ k, k ^ 2 = (Nat.digits 10 n).sum := h₃
        -- We will check each number from 10 to 99 to see if it satisfies the condition
        interval_cases n <;> norm_num [Nat.digits_len, Nat.div_eq_of_lt, Nat.mod_eq_of_lt, Nat.pow_succ] at h₇ ⊢ <;>
          (try omega) <;>
          (try
            {
              rcases h₇ with ⟨k, hk⟩
              have h₈ : k ≤ 18 := by
                nlinarith
              have h₉ : k ≥ 0 := by
                nlinarith
              interval_cases k <;> norm_num at hk ⊢ <;>
                (try omega) <;>
                (try
                  {
                    simp_all (config := {decide := true})
                  })
            }) <;>
          (try
            {
              aesop
            }) <;>
          (try
            {
              simp_all (config := {decide := true})
            })
      -- Now we know n is one of the specified numbers, so we can conclude the proof
      simp_all (config := {decide := true})
    · -- Prove the reverse inclusion: if n is in the RHS, then n is in the LHS
      intro n hn
      have h₁ : n = 10 ∨ n = 13 ∨ n = 22 ∨ n = 31 ∨ n = 40 ∨ n = 18 ∨ n = 27 ∨ n = 36 ∨ n = 45 ∨ n = 54 ∨ n = 63 ∨ n = 72 ∨ n = 81 ∨ n = 90 ∨ n = 79 ∨ n = 88 ∨ n = 97 := by
        simp_all (config := {decide := true})
      -- We will check each number to see if it satisfies the condition
