theorem algebra_325500 (x y : ℤ) (hx : x > 0) (hy : y > 0)
    (h : x^2 + 6 * x * y - 7 * y^2 = 2009) :
    (x = 252 ∧ y = 251) ∨ (x = 42 ∧ y = 35) ∨ (x = 42 ∧ y = 1) := by
  have h_main : (x = 252 ∧ y = 251) ∨ (x = 42 ∧ y = 35) ∨ (x = 42 ∧ y = 1) := by
    have h₁ : x > 0 := hx
    have h₂ : y > 0 := hy
    have h₃ : x^2 + 6 * x * y - 7 * y^2 = 2009 := h
    have h₄ : y ≤ 44 := by
      by_contra h₅
      have h₆ : y ≥ 45 := by linarith
      have h₇ : x^2 + 6 * x * y - 7 * y^2 = 2009 := h₃
      have h₈ : x ≤ 90 := by
        nlinarith [sq_nonneg (x - 3 * y), sq_nonneg (x + 3 * y), sq_nonneg (x - 3 * y + 6 * y),
          sq_nonneg (x + 3 * y - 6 * y)]
      have h₉ : x ≥ 1 := by linarith
      have h₁₀ : y ≥ 45 := by linarith
      interval_cases x <;> omega
    have h₅ : y ≥ 1 := by linarith
    -- We now check all possible values of y from 1 to 44
    interval_cases y <;> (try omega) <;>
    (try {
      have h₆ : x ≤ 90 := by
        nlinarith [sq_nonneg (x - 3 * y), sq_nonneg (x + 3 * y), sq_nonneg (x - 3 * y + 6 * y),
          sq_nonneg (x + 3 * y - 6 * y)]
      have h₇ : x ≥ 1 := by linarith
      interval_cases x <;> norm_num at h₃ ⊢ <;> (try omega) <;> (try
        {
          nlinarith
        }) <;> (try
        {
          ring_nf at h₃ ⊢ <;> omega
        })
    }) <;>
    (try {
      omega
    }) <;>
    (try {
      norm_num at h₃ ⊢
      <;>
      (try omega) <;>
      (try
        {
          have h₆ : x ≤ 90 := by
            nlinarith [sq_nonneg (x - 3 * y), sq_nonneg (x + 3 * y), sq_nonneg (x - 3 * y + 6 * y),
              sq_nonneg (x + 3 * y - 6 * y)]
          have h₇ : x ≥ 1 := by linarith
          interval_cases x <;> norm_num at h₃ ⊢ <;> (try omega) <;> (try
            {
              nlinarith
            }) <;> (try
            {
              ring_nf at h₃ ⊢ <;> omega
            })
        })
    }) <;>
    (try {
      aesop
    }) <;>
    (try {
      norm_num at h₃ ⊢ <;>
      (try omega) <;>
      (try
        {
          ring_nf at h₃ ⊢ <;>
          omega
        })
    }) <;>
    (try {
      aesop
    }) <;>
    (try {
      omega
    })
    <;>
    (try {
      aesop
    })
    <;>
    (try {
      omega
    })
  exact h_main

